# Termenii glosarului: (id, termen, definiție HTML). Ordinea finală se face alfabetic (română) în build_glosar.py.
L = lambda n: f'lectie.html#cap-{n}'
TERMS = [
 ('pip', 'Pip', f'Cea mai mică mișcare „standard” a prețului unei perechi valutare. La majoritatea perechilor, 1 pip = 0,0001 (a patra zecimală); la perechile cu yen (JPY), 1 pip = 0,01. Detalii în <a href="{L(3)}">capitolul 3 al cursului</a>.'),
 ('punct', 'Punct (pipette)', 'O zecimală în plus față de pip: 10 puncte = 1 pip. Platformele precum MetaTrader afișează prețul cu 5 zecimale (3 la JPY), iar distanțele apar adesea în puncte, nu în pips.'),
 ('lot', 'Lot', f'Unitatea de măsură a mărimii poziției. 1 lot standard = 100.000 de unități din valuta de bază, 0,10 loturi = 10.000, iar 0,01 loturi (micro) = 1.000. Câte loturi deschizi afli cu <a href="calculator.html">calculatorul de lot</a>.'),
 ('valoarea-pipului', 'Valoarea pipului', f'Cât câștigi sau pierzi la o mișcare de 1 pip. La EURUSD, 1 pip pe 1 lot valorează 10 USD; la alte perechi depinde de curs. Vezi exemplele din <a href="{L(3)}">capitolul 3</a>.'),
 ('spread', 'Spread', f'Diferența dintre prețul de cumpărare (ask) și cel de vânzare (bid). Este principalul cost al unei tranzacții și crește la știri, noaptea sau la redeschiderea pieței. Vezi <a href="{L(1)}">capitolul 1</a>.'),
 ('bid-ask', 'Bid și ask', 'Bid este prețul la care poți vinde, ask prețul la care poți cumpăra (mereu puțin mai mare). Cumperi la ask și vinzi la bid, iar diferența dintre ele este spread-ul.'),
 ('swap', 'Swap', f'Costul (uneori un mic câștig) pentru ținerea unei poziții peste noapte, în funcție de dobânzile celor două valute. La majoritatea brokerilor, miercurea se aplică triplu, pentru weekend. Vezi <a href="{L(3)}">capitolul 3</a>.'),
 ('comision', 'Comision', 'O taxă fixă pe lot, percepută de unele conturi în loc de un spread mai mare. Când compari brokerii, compară costul total: spread, comision și swap.'),
 ('levier', 'Levier', f'Îți permite să deschizi o poziție mult mai mare decât banii din cont: cu 1:30, la 1 € din cont controlezi 30 €. Profitul și pierderea se calculează la toată poziția, deci levierul mărește la fel de mult pierderile. Vezi <a href="{L(4)}">capitolul 4</a>.'),
 ('marja', 'Marjă', f'Partea din cont blocată de broker ca garanție pentru o poziție deschisă: marja = valoarea poziției ÷ levier. Nu este un cost, ci bani blocați cât timp poziția e deschisă. Vezi <a href="{L(4)}">capitolul 4</a>.'),
 ('margin-call', 'Margin call', 'Avertismentul brokerului că marja liberă s-a terminat și contul se apropie de închiderea forțată a pozițiilor. Nivelul exact îl stabilește brokerul.'),
 ('stop-out', 'Stop out', 'Nivelul la care brokerul îți închide automat pozițiile, pentru că equity a scăzut prea mult față de marja folosită. În UE, pentru clienții retail, închiderea are loc când capitalul scade sub 50% din marja inițială necesară.'),
 ('equity', 'Equity (capital curent)', 'Soldul contului plus sau minus profitul ori pierderea pozițiilor încă deschise. Marja și stop out-ul se calculează din equity, nu din sold.'),
 ('sold', 'Sold (balance)', 'Banii din cont fără pozițiile deschise: depunerile, plus și minus rezultatul tranzacțiilor deja închise. Se schimbă doar când închizi o poziție.'),
 ('drawdown', 'Drawdown', f'Cât a scăzut contul de la cel mai înalt nivel atins, de obicei în procente. Pierderile mari sunt greu de recuperat: după −50% ai nevoie de +100% ca să revii. Vezi <a href="{L(6)}">capitolul 6</a>.'),
 ('stop-loss', 'Stop loss (SL)', f'Ordinul care îți închide automat poziția pe pierdere la un preț stabilit dinainte. Îl pui acolo unde ideea ta devine greșită și nu îl muți niciodată mai departe. Vezi <a href="{L(5)}">capitolul 5</a>.'),
 ('take-profit', 'Take profit (TP)', f'Ordinul care îți închide automat poziția pe profit, la ținta stabilită. Se pune logic, înaintea unei zone de unde prețul se poate întoarce. Vezi <a href="{L(5)}">capitolul 5</a>.'),
 ('trailing-stop', 'Trailing stop', 'Un stop loss care urmărește prețul la o distanță fixă când tranzacția merge în favoarea ta și nu se mai întoarce. Atenție: în MetaTrader funcționează doar cât timp platforma este deschisă.'),
 ('break-even', 'Break-even', 'Punctul în care nu câștigi și nu pierzi. „Muți SL-ul la break-even” înseamnă să îl duci la prețul de intrare. Rata de câștig de break-even este procentul minim de tranzacții câștigate ca să fii pe zero: 1 ÷ (1 + R).'),
 ('raport-risc-castig', 'Raport risc/câștig (R:R)', f'Compară cât riști cu cât poți câștiga: SL de 25 pips și TP de 50 pips înseamnă 1:2. Cu 1:2 ai nevoie de cel puțin 33,3% tranzacții câștigate ca să fii pe zero, înainte de costuri. Îl calculezi cu <a href="calculator.html#risc-recompensa">calculatorul risk/reward</a>.'),
 ('managementul-riscului', 'Managementul riscului (risk management)', f'Regulile care îți protejează contul: risc de maximum 1% pe tranzacție, stop loss mereu, lot calculat după risc și limite de pierdere pe zi și pe săptămână. Vezi <a href="{L(6)}">capitolul 6</a> și <a href="reguli.html">regulile de bază</a>.'),
 ('ordin-market', 'Ordin market', f'Intri imediat, la prețul curent disponibil. Este cel mai simplu tip de ordin. Vezi <a href="{L(5)}">capitolul 5</a>.'),
 ('ordin-limit', 'Ordin limit', 'Un ordin în așteptare la un preț mai bun decât cel curent: buy limit sub preț, sell limit deasupra. Se folosește când aștepți o revenire a prețului.'),
 ('ordin-stop', 'Ordin stop', 'Un ordin în așteptare care intră când prețul confirmă direcția: buy stop deasupra prețului curent, sell stop sub el. Se folosește des la breakout-uri.'),
 ('slippage', 'Slippage', 'Diferența dintre prețul cerut și cel la care s-a executat ordinul. Apare mai ales la știri sau când piața se mișcă foarte repede și poate fi în favoarea sau în defavoarea ta.'),
 ('gap', 'Gap', 'Un salt al prețului peste un interval în care nu s-a tranzacționat, de obicei între închiderea de vineri și deschiderea de luni sau la știri importante. Un gap poate sări peste stop loss-ul tău, iar ieșirea are loc la primul preț disponibil.'),
 ('pereche-majora', 'Pereche majoră', 'O pereche formată din dolarul american și una dintre valutele mari: EURUSD, GBPUSD, USDJPY, USDCHF, AUDUSD, USDCAD, NZDUSD. Au lichiditate mare și, de obicei, cele mai mici costuri.'),
 ('pereche-minora', 'Pereche minoră (cross)', 'O pereche între valute importante, dar fără dolarul american, de exemplu EURGBP, EURJPY sau GBPJPY. Costurile sunt de obicei puțin mai mari decât la majore.'),
 ('pereche-exotica', 'Pereche exotică', 'O valută importantă împerecheată cu valuta unei economii mai mici sau emergente, de exemplu USDTRY sau EURPLN. Spread-ul e mai mare, iar mișcările pot fi bruște. Pentru început, rămâi la majore.'),
 ('valuta-baza-cotata', 'Valută de bază și valută cotată', f'Într-o pereche, prima valută este cea de bază, a doua cea cotată. EURUSD = 1,1000 înseamnă că 1 euro (baza) costă 1,10 dolari (cotată). Vezi <a href="{L(1)}">capitolul 1</a>.'),
 ('long-short', 'Long și short', 'Long (buy) înseamnă că te aștepți ca prețul să crească, short (sell) că te aștepți să scadă. Pe Forex poți tranzacționa la fel de simplu în ambele direcții.'),
 ('bullish', 'Bullish', 'Optimist pentru creșterea prețului. O piață bullish are, în general, maxime și minime din ce în ce mai înalte. O lumânare bullish se închide peste deschidere.'),
 ('bearish', 'Bearish', 'Pesimist, cu așteptare de scădere a prețului. O piață bearish are, în general, maxime și minime din ce în ce mai joase. O lumânare bearish se închide sub deschidere.'),
 ('trend', 'Trend', 'Direcția generală a prețului într-o perioadă: ascendent (maxime și minime tot mai înalte), descendent (tot mai joase) sau lateral. Îl vezi cel mai clar pe intervalele mari, D1 și H4.'),
 ('suport', 'Suport', f'O zonă de preț unde scăderile s-au oprit de mai multe ori, pentru că acolo au apărut cumpărători. La un buy, stop loss-ul se pune de obicei sub un suport. Vezi și <a href="patternuri.html">patternurile de grafic</a>.'),
 ('rezistenta', 'Rezistență', 'O zonă de preț unde creșterile s-au oprit de mai multe ori, pentru că acolo au apărut vânzători. Un suport spart poate deveni rezistență, și invers.'),
 ('breakout', 'Breakout', f'Ieșirea prețului dintr-o zonă sau formă, de exemplu peste o rezistență sau din <a href="patternuri.html#triunghi">triunghi</a>. Multe breakout-uri sunt false, de aceea mulți traderi așteaptă închiderea lumânării sau un retest.'),
 ('retest', 'Retest', 'Revenirea prețului la nivelul tocmai spart, înainte să continue în direcția breakout-ului. De exemplu, o rezistență spartă este testată de sus, ca suport.'),
 ('lumanare', 'Lumânare (candlestick)', f'Reprezentarea prețului pe un interval: deschiderea, închiderea, maximul și minimul. Verde dacă s-a închis peste deschidere, roșie dacă sub. Vezi <a href="{L(2)}">capitolul 2</a>.'),
 ('timeframe', 'Timeframe', f'Intervalul de timp al unei lumânări: M15 (15 minute), H1 (o oră), H4 (4 ore), D1 (o zi), W1 (o săptămână). Pe intervalele mici apare mult zgomot. Vezi <a href="{L(2)}">capitolul 2</a>.'),
 ('volatilitate', 'Volatilitate', 'Cât de mult și cât de repede se mișcă prețul. Volatilitatea crește la știri și în sesiunile active. Un stop loss prea strâns într-o piață volatilă este atins des.'),
 ('lichiditate', 'Lichiditate', f'Cât de ușor se poate cumpăra sau vinde fără să miști prețul. Lichiditatea mare înseamnă spread mic și execuție bună; cea mai mare este de obicei la suprapunerea <a href="sesiuni.html">sesiunilor</a> Londra și New York.'),
 ('sesiune', 'Sesiune de tranzacționare', 'Intervalul în care un centru financiar mare este activ: Sydney, Tokyo, Londra, New York. Pe pagina <a href="sesiuni.html">Sesiuni</a> vezi live ce sesiuni sunt deschise, în ora ta.'),
 ('nfp', 'NFP (Non-Farm Payrolls)', 'Raportul lunar despre locurile de muncă create în SUA în afara agriculturii, publicat de obicei în prima vineri a lunii, la 15:30 ora României (14:30 în câteva săptămâni pe an, când SUA și Europa schimbă ora la date diferite). Este una dintre știrile care mișcă cel mai mult piața. Îl găsești în <a href="calendar.html">calendarul economic</a>.'),
 ('cpi', 'CPI (inflația)', 'Indicele prețurilor de consum, principala măsură a inflației. O inflație peste așteptări poate schimba planurile băncii centrale privind dobânzile și mișcă puternic valuta. Datele apar în <a href="calendar.html">calendarul economic</a>.'),
 ('banca-centrala', 'Bancă centrală', 'Instituția care stabilește dobânda de politică monetară a unei valute, de exemplu Fed (SUA) sau BCE (zona euro). Deciziile și discursurile băncilor centrale sunt printre cele mai importante evenimente pentru Forex.'),
 ('cfd', 'CFD', f'Contract pentru diferență: un instrument care urmărește prețul unui activ fără să îl deții. Câștigi sau pierzi diferența de preț, cu levier. La brokerii pentru persoane fizice, Forex-ul se tranzacționează de obicei prin CFD-uri. Vezi <a href="{L(1)}">capitolul 1</a>.'),
 ('broker', 'Broker', 'Firma prin care ai acces la piață: deschizi un cont, depui bani și tranzacționezi pe o platformă. Verifică întotdeauna reglementarea, costurile și cât de simplu îți retragi banii.'),
 ('ecn-market-maker', 'ECN și market maker', 'Un broker ECN transmite ordinele către furnizori de lichiditate, de obicei cu spread mic plus comision. Un market maker este el însuși contrapartea tranzacțiilor tale. Ambele modele pot fi corecte, dacă brokerul este reglementat.'),
 ('cont-demo', 'Cont demo', f'Un cont cu bani virtuali și prețuri reale, oferit gratuit de brokeri. Acolo înveți platforma și îți testezi planul fără risc, cu aceleași reguli ca pe real. Vezi <a href="{L(8)}">capitolul 8</a>.'),
 ('backtest', 'Backtest', 'Testarea unei strategii pe date din trecut, ca să vezi cum s-ar fi comportat. Rezultatele din trecut nu garantează rezultate viitoare, dar te ajută să vezi dacă regulile au sens.'),
 ('jurnal', 'Jurnal de trading', f'Notițele despre fiecare tranzacție: perechea, motivul intrării, SL, TP, rezultatul în R și dacă ai respectat planul. Poți folosi gratuit <a href="jurnal.html">jurnalul de pe site</a>.'),
 ('overtrading', 'Overtrading', f'Prea multe tranzacții, din plictiseală sau din dorința de a recupera. Antidotul: intri doar pe setup-urile din planul tău. Vezi <a href="{L(7)}">capitolul 7</a>.'),
 ('fomo', 'FOMO', f'Frica de a rata o mișcare (Fear Of Missing Out): sari târziu într-o tranzacție, fără un stop loss logic. O intrare ratată nu este o pierdere. Vezi <a href="{L(7)}">capitolul 7</a>.'),
 ('revenge-trading', 'Revenge trading', f'Trading din răzbunare: după o pierdere vrei să „recuperezi” imediat, de obicei cu un lot mai mare. Antidotul: după 2 pierderi la rând, închizi platforma până a doua zi. Vezi <a href="{L(7)}">capitolul 7</a>.'),
 ('swing-trading', 'Swing trading', 'Un stil în care ții pozițiile de la câteva zile până la câteva săptămâni și lucrezi în principal pe D1 și H4. Este stilul meu și, pentru un începător, unul mai iertător: ai timp să gândești.'),
 ('day-trading', 'Day trading', 'Un stil în care deschizi și închizi pozițiile în aceeași zi, fără să le ții peste noapte. Cere mult timp în fața ecranului și decizii rapide.'),
 ('scalping', 'Scalping', 'Un stil foarte rapid, cu tranzacții de câteva secunde sau minute, pe intervale mici. Costurile (spread, comision) cântăresc mult, iar pentru un începător este cel mai greu stil.'),
 ('esma', 'ESMA', f'Autoritatea Europeană pentru Valori Mobiliare și Piețe. Regulile ei pentru CFD-uri protejează clienții retail din UE: levier maxim 1:30 pe perechile majore, închiderea pozițiilor la 50% din marjă și protecție la sold negativ. Vezi <a href="{L(4)}">capitolul 4</a>.'),
 ('sold-negativ', 'Protecție la sold negativ', 'Regula prin care, la brokerii din UE, un client retail nu poate pierde mai mult decât banii din cont. Brokerii din afara UE nu sunt obligați să o aplice.'),
]
